fn is_digits(t: Str) -> Bool {
  if t.is_empty() {
    return false
  }
  return t.chars().all(fn(c) => "0123456789".contains(c))
}

fn is_number(t: Str) -> Bool {
  if t.starts_with("-") {
    return is_digits(t.slice(1, t.len()))
  }
  return is_digits(t)
}

fn is_lower_name(t: Str) -> Bool {
  if t.is_empty() {
    return false
  }
  return t.chars().all(fn(c) => "abcdefghijklmnopqrstuvwxyz".contains(c))
}

fn is_term(t: Str) -> Bool {
  return is_number(t) or is_lower_name(t)
}

fn line_ok(parts: List[Str]) -> Bool {
  let n = parts.len()
  if n < 3 or n % 2 == 0 {
    return false
  }
  if not is_lower_name(parts.get_or(0, "")) {
    return false
  }
  if parts.get_or(1, "") != "=" {
    return false
  }
  var k = 2
  while k < n {
    if not is_term(parts.get_or(k, "")) {
      return false
    }
    if k + 1 < n {
      let op = parts.get_or(k + 1, "")
      if op != "+" and op != "-" {
        return false
      }
    }
    k = k + 2
  }
  return true
}

fn term_value(t: Str, vars: Map[Str, Int]) -> Option[Int] {
  if is_number(t) {
    if t.starts_with("-") {
      return Some(0 - t.slice(1, t.len()).to_int().unwrap_or(0))
    }
    return Some(t.to_int().unwrap_or(0))
  }
  return vars.get(t)
}

pub fn run_vars(lines: List[Str]) -> Result[Map[Str, Int], Str] {
  var vars: Map[Str, Int] = Map {}
  for line in lines {
    let parts = line.split(" ")
    if not line_ok(parts) {
      return Err("syntax error")
    }
    let n = parts.len()
    var acc = 0
    var op = "+"
    var k = 2
    while k < n {
      let t = parts.get_or(k, "")
      match term_value(t, vars) {
        Some(v) => {
          if op == "+" {
            acc = acc + v
          } else {
            acc = acc - v
          }
        },
        None => { return Err("undefined " + t) },
      }
      if k + 1 < n {
        op = parts.get_or(k + 1, "")
      }
      k = k + 2
    }
    vars = vars.set(parts.get_or(0, ""), acc)
  }
  return Ok(vars)
}
